#include <Servo.h>

Servo myservo;

void setup() {
  myservo.attach(14, 500, 2400); 
}

void loop() {
  myservo.write(0);
  delay(2000);

  myservo.write(180);
  delay(2000);

  myservo.write(0);
  delay(2000);

  myservo.write(180);
  delay(2000);

  myservo.write(0);
  delay(2000);

  myservo.write(180);
  delay(2000);
}
